import{_ as t,o as a,c as i,ag as o}from"./chunks/framework.BXn5fPR3.js";const m=JSON.parse('{"title":"QPlay /QPlay/Control","description":"","frontmatter":{},"headers":[],"relativePath":"services/qplay.md","filePath":"services/qplay.md"}'),r={name:"services/qplay.md"};function s(d,e,n,l,c,h){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="qplay-qplay-control" tabindex="-1"><code>QPlay</code> <code>/QPlay/Control</code> <a class="header-anchor" href="#qplay-qplay-control" aria-label="Permalink to &quot;`QPlay` `/QPlay/Control`&quot;">​</a></h1><p><strong>visibility</strong> <code>advertised</code> · <strong>status</strong> <code>confirmed</code></p><p>This service exists for one integration: QPlay, the protocol Tencent&#39;s QQ Music uses to send music to speakers, which is the equivalent of a &#39;cast to device&#39; feature inside China&#39;s dominant streaming service. It has a single command, the authentication handshake that begins a QPlay session: the app sends a seed value and the player returns the corresponding response, proving it can participate in the exchange. On this build the command is fully present, because QPlay shipped only on units sold for the Chinese market, which is why most users have never seen it.</p><details class="details custom-block"><summary>Technical details</summary><p>QPlay (QQ Music) authentication service stub; the extractor resolved no handler for QPlayAuth: likely registered but dispatch entry unresolved in this build.</p></details><h2 id="availability" tabindex="-1">Availability <a class="header-anchor" href="#availability" aria-label="Permalink to &quot;Availability&quot;">​</a></h2><ul><li>capability flags <code>0x800</code></li><li>enabled gate: <code>xor(*(r3-in+0x571c))</code> at <code>0x10195670</code> (field_inverted)</li><li>Service object constructed at zone-player init; always registered in this build - no feature-gate found at the registration site</li></ul><h2 id="dispatch" tabindex="-1">Dispatch <a class="header-anchor" href="#dispatch" aria-label="Permalink to &quot;Dispatch&quot;">​</a></h2><ul><li>router <code>0x101953c8</code>, cap flags <code>0x800</code></li><li>dispatcher <code>0x1073a4f0</code> kind <code>strcmp</code></li></ul><h2 id="actions" tabindex="-1">Actions <a class="header-anchor" href="#actions" aria-label="Permalink to &quot;Actions&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Visibility</th><th>Reachability</th><th>Confidence</th><th>Dispatch</th><th>Error codes</th></tr></thead><tbody><tr><td><code>QPlayAuth</code></td><td>advertised</td><td>callable</td><td><code>confirmed</code></td><td>strcmp-dispatched</td><td>401, 402</td></tr></tbody></table><h3 id="qplayauth" tabindex="-1"><code>QPlayAuth</code> <a class="header-anchor" href="#qplayauth" aria-label="Permalink to &quot;`QPlayAuth`&quot;">​</a></h3><p>visibility <code>advertised</code> · reachability <code>callable</code> · confidence <code>confirmed</code> · dispatch <code>strcmp-dispatched</code></p><p>The QPlay login handshake, the first step when a QQ Music app wants to send audio to this speaker. The app presents a &#39;seed&#39; challenge value and the player computes the matching response code, proving it speaks the QPlay protocol and unlocking the session that streams music afterward. Only used by the Tencent integration, so it is meaningless to ordinary apps.</p><details class="details custom-block"><summary>Technical details</summary><p>QPlay authentication handshake (Tencent seed-&gt;code exchange, fully decoded): dispatcher f_1073a4f0 strcmp-matches &#39;QPlayAuth&#39; -&gt; exec f_1073a5d0. Exec calls req-&gt;v[+0x1c] to fetch arg &#39;Seed&#39; (0x10f11d64), parses it via f_1056157c into a stack buffer capped at 0x80 bytes, then gates on req-&gt;v[+0x08] (parse-ok check) -&gt; emits 402 (0x192) Invalid Args on failure; 401 (0x191) for unknown action names. On success it calls impl-&gt;v[+0x08](impl, seedBuf, codeOut, 0x80, midOut, 0x15, didOut, 0x15) where impl = req-&gt;member[+0x04]: Code buffer cap 0x80, MID and DID buffers cap 0x15 (20-char strings + NUL). Each output is emitted as an individual out-arg via req-&gt;v[+0x24] with names &#39;Code&#39;(0x10eb95c4)/&#39;MID&#39;(0x10f11d6c)/&#39;DID&#39;(0x10f11d70), value serialized through the out-arg object&#39;s v[+0x10] emitter; response committed via req-&gt;v[+0x0c]. The Seed-&gt;Code transform lives inside the impl member fn (no literals, crypto inlined or via shared hash lib) and is the only undecoded part. NOTE: an earlier attribution of the compute fn to f_104666b4 was wrong - that fn is a MuseDebugInfo formatter (&#39;%s, %u, %u, %u&#39; @0x10f94c88, &#39;MuseDebugInfo&#39; @0x10f94c98).</p></details><h4 id="inputs" tabindex="-1">Inputs <a class="header-anchor" href="#inputs" aria-label="Permalink to &quot;Inputs&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Required</th><th>Values / range</th><th>Default</th></tr></thead><tbody><tr><td><code>Seed</code></td><td>string argument</td><td>yes</td><td>seed string consumed verbatim by auth hash f_10906304 / max 127 chars</td><td>none; required input</td></tr></tbody></table><ul><li><strong><code>Seed</code></strong>: client seed string feeding the auth-code computation f_10906304; required <ul><li>validation: required-arg parse precedes impl call; req-&gt;v[+0x08] gate emits 402 on failure</li><li>buffer cap: <code>0x80</code></li></ul></li></ul><h4 id="outputs" tabindex="-1">Outputs <a class="header-anchor" href="#outputs" aria-label="Permalink to &quot;Outputs&quot;">​</a></h4><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Values / range</th></tr></thead><tbody><tr><td><code>Code</code></td><td></td><td>none</td></tr><tr><td><code>MID</code></td><td></td><td>none</td></tr><tr><td><code>DID</code></td><td></td><td>none</td></tr></tbody></table><details class="details custom-block"><summary>Technical analysis</summary><h4 id="validation-confirmed" tabindex="-1">Validation <code>confirmed</code> <a class="header-anchor" href="#validation-confirmed" aria-label="Permalink to &quot;Validation `confirmed`&quot;">​</a></h4><p>req-&gt;v[+0x08] validation gate; failure emits 402 (literal 0x192 at 0x1073a6b8)</p><details class="details custom-block"><summary>Evidence (2)</summary><ul><li>@ 0x1073a5d0; validate gate + 0x192 literal</li><li>@ 0x1073a6b8; 0x192 -&gt; req-&gt;v[+0x14]</li></ul></details></details><h4 id="requirements-preconditions-confirmed" tabindex="-1">Requirements / preconditions <code>confirmed</code> <a class="header-anchor" href="#requirements-preconditions-confirmed" aria-label="Permalink to &quot;Requirements / preconditions `confirmed`&quot;">​</a></h4><p>Seed is required: parse via f_1056157c precedes the impl call and the req-&gt;v[+0x08] gate rejects missing/malformed args with 402</p><details class="details custom-block"><summary>Evidence (1)</summary><ul><li>@ 0x1073a5d0; required-arg parse order + gate</li></ul></details><h4 id="state-dependencies-confirmed" tabindex="-1">State dependencies <code>confirmed</code> <a class="header-anchor" href="#state-dependencies-confirmed" aria-label="Permalink to &quot;State dependencies `confirmed`&quot;">​</a></h4><p>auth computation reads device-identity material via f_106453a8/f_1064548c lookups inside impl f_104666b4; impl object injected into svc+4 by ctor f_1073a768 (called at 0x1018f28c)</p><details class="details custom-block"><summary>Evidence (2)</summary><ul><li>@ 0x104666b4; device-material lookups</li><li>@ 0x1018f28c; impl ctor injection site</li></ul></details><h4 id="side-effects" tabindex="-1">Side effects <a class="header-anchor" href="#side-effects" aria-label="Permalink to &quot;Side effects&quot;">​</a></h4><ul><li>Stores the action-name pointer into ctx+0x70 member +0xe0 and TLS+0x28 (f_100ad1bc/f_100a9750); auth computation itself returns 0 with no persistent mutation in this build.</li></ul><h4 id="state-transitions-confirmed" tabindex="-1">State transitions <code>confirmed</code> <a class="header-anchor" href="#state-transitions-confirmed" aria-label="Permalink to &quot;State transitions `confirmed`&quot;">​</a></h4><p>none: no state-machine mutation in handler f_1073a5d0 or impl f_104666b4 beyond the action-name/TLS stores</p><details class="details custom-block"><summary>Evidence (1)</summary><ul><li>@ 0x104666b4; read-only auth computation + return 0</li></ul></details><h4 id="events-confirmed" tabindex="-1">Events <code>confirmed</code> <a class="header-anchor" href="#events-confirmed" aria-label="Permalink to &quot;Events `confirmed`&quot;">​</a></h4><p>none emitted: impl f_104666b4 returns 0 unconditionally with no event/notify call; the only side effect is the action-name store into ctx+0x70 member +0xe0 and TLS+0x28</p><details class="details custom-block"><summary>Evidence (1)</summary><ul><li>@ 0x104666b4; unconditional return 0, no event emitter calls</li></ul></details><h4 id="return-behavior-confirmed" tabindex="-1">Return behavior <code>confirmed</code> <a class="header-anchor" href="#return-behavior-confirmed" aria-label="Permalink to &quot;Return behavior `confirmed`&quot;">​</a></h4><p>impl returns 0 unconditionally -&gt; success response commits Code/MID/DID via req-&gt;v[+0x24] emitters then req-&gt;v[+0x0c]; nonzero would surface via the same fault/commit path</p><details class="details custom-block"><summary>Evidence (2)</summary><ul><li>@ 0x104666b4; return 0</li><li>@ 0x1073a5d0; emit + commit tail</li></ul></details><h4 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h4><p><strong><code>402</code></strong> <code>confirmed</code></p><p>request-validate gate failed (req-&gt;v[+0x08] returned 0)</p><ul><li>req-&gt;v[+0x08] request gate fails (handler literal 0x192 at 0x1073a6b8)</li></ul><p><strong><code>401</code></strong> <code>confirmed</code></p><p>unknown action name on QPlay dispatcher</p><ul><li>action name != QPlayAuth (dispatcher strcmp) (dispatcher fault 0x1073a548)</li></ul><p><strong><code>401</code></strong> <code>confirmed</code></p><p>action-name strcmp miss in wrapper f_1073a4f0 -&gt; req v[+0x14] emit 0x191</p><ul><li>dispatched action name != &quot;QPlayAuth&quot; (strcmp fallthrough)</li></ul><p>:::</p><details class="details custom-block"><summary>Implementation &amp; reverse-engineering evidence</summary><ul><li><p>handler <code>0x1073a4f0</code></p></li><li><p>Dispatcher f_1073a4f0 strcmp-matches &quot;QPlayAuth&quot;, stores the action name into ctx+0x70 member +0xe0 and into TLS+0x28 via f_100ad1bc/f_100a9750, then calls svc-&gt;v[+0x0c] = f_1073a5d0: parses required Seed (cap 0x80 via f_1056157c), req-&gt;v[+0x08] gate (else 402), then impl-&gt;v[+0x08] = f_104666b4 which computes Code via f_10906304 over the Seed plus device material (f_106453a8/f_1064548c lookups), formats a %u device value into the MID/DID buffers via snprintf_chk, and unconditionally returns 0. Success emits Code/MID/DID via req-&gt;v[+0x24] then commits via req-&gt;v[+0x0c].</p></li><li><p>@ 0x1073a528; strcmp dispatch site</p></li><li><p>fn 0x1073a5d0; svc vfunc +0x0c: Seed parse, 402 gate, impl call, Code/MID/DID emission</p></li><li><p>fn 0x104666b4; impl: auth-code computation + %u format; unconditional return 0</p></li></ul></details><h2 id="state-variables" tabindex="-1">State variables <a class="header-anchor" href="#state-variables" aria-label="Permalink to &quot;State variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Evented</th><th>Description</th></tr></thead><tbody><tr><td><code>A_ARG_TYPE_Seed</code></td><td>string</td><td>no</td><td>argument-type state variable (SCPD type declaration for action args; not device state, not evented)</td></tr><tr><td><code>A_ARG_TYPE_Code</code></td><td>string</td><td>no</td><td>argument-type state variable (SCPD type declaration for action args; not device state, not evented)</td></tr><tr><td><code>A_ARG_TYPE_MID</code></td><td>string</td><td>no</td><td>argument-type state variable (SCPD type declaration for action args; not device state, not evented)</td></tr><tr><td><code>A_ARG_TYPE_DID</code></td><td>string</td><td>no</td><td>argument-type state variable (SCPD type declaration for action args; not device state, not evented)</td></tr></tbody></table><h2 id="events" tabindex="-1">Events <a class="header-anchor" href="#events" aria-label="Permalink to &quot;Events&quot;">​</a></h2><ul><li><strong>Mechanism:</strong> GENA SUBSCRIBE accepted at /QPlay/Event via f_105e8290 (NT:upnp:event + NTS:upnp:propchange validated); notify emission path not recovered for this service</li><li>Only 3 LastChange/event doc templates exist in rodata (RCS 0x10e88928, AVT 0x10eb29e8, Queue 0x10ed1c6c); the event-namespace registry at 0x10f0bedc-0x10f0bfa8 lists only AVT/RCS/Queue - proven: this service emits no LastChange payload</li><li>No WSS registry name maps to this service in the 73-entry table; event surface likely absent or folded into another namespace</li></ul><details class="details custom-block"><summary>Technical details</summary><ul><li><strong>notify_path:</strong> &#39;updateSharedTQPlayMode&#39; worker (&#39;...bad context!&#39; log) is the QPlay state-update path; X_QPlay_SoftwareCapability static; no dedicated emitter recovered</li></ul></details><h2 id="dispatcher-level-errors" tabindex="-1">Dispatcher-level errors <a class="header-anchor" href="#dispatcher-level-errors" aria-label="Permalink to &quot;Dispatcher-level errors&quot;">​</a></h2><details class="details custom-block"><summary>Technical details</summary><p><strong><code>401</code></strong> <code>strong</code></p><p>unknown action name for this service; dispatcher emits a SOAP fault (401 Invalid Action family) without invoking any handler</p><ul><li>Request action name matches no entry in the service dispatch table after the name-table search</li></ul></details><p>Implementation sources (recovered): <code>compiled lib (qplay): no path literal</code></p><details class="details custom-block"><summary>Service evidence (3)</summary><ul><li>@ 0x101953c8; service router function</li><li>@ 0x10f11d48; service vtable</li><li>@ 0x1073a4f0; service dispatcher</li></ul></details>',58)])])}const p=t(r,[["render",s]]);export{m as __pageData,p as default};
